input.script:
() => {
  const input = document.querySelector('input[type="checkbox"]');
  if (input) {
    return {
      found: true,
      checked: input.checked,
      ariaLabel: input.getAttribute('aria-label'),
      id: input.id,
      outerHTML: input.outerHTML.substring(0, 500)
    };
  }
  return { found: false };
}

async () => {
  // Find the checkbox and its container
  const inputs = document.querySelectorAll('input[type="checkbox"]');
  const results = [];
  for (const input of inputs) {
    const rect = input.getBoundingClientRect();
    results.push({
      ariaLabel: input.getAttribute('aria-label'),
      id: input.id,
      name: input.name,
      rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
      visible: rect.width > 0 && rect.height > 0,
      disabled: input.disabled,
      readOnly: input.readOnly
    });
  }
  return { inputs: results, count: inputs.length };
}

() => {
  const input = document.querySelector('input[type="checkbox"]');
  if (!input) return { error: 'No checkbox found' };

  // Get the parent element to click on (the visible checkbox area)
  const parent = input.parentElement;
  const rect = parent.getBoundingClientRect();

  // Dispatch a click event
  const clickEvent = new MouseEvent('click', {
    view: window,
    bubbles: true,
    cancelable: true,
    clientX: rect.x + rect.width / 2,
    clientY: rect.y + rect.height / 2
  });

  input.dispatchEvent(clickEvent);
  parent.dispatchEvent(clickEvent);

  return {
    success: true,
    checked: input.checked,
    parentTag: parent.tagName,
    rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
  };
}

async () => {
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (!checkbox) return { error: 'No checkbox found' };

  // Get the visible checkbox element
  const labelOrParent = checkbox.closest('label') || checkbox.parentElement;
  const rect = labelOrParent.getBoundingClientRect();

  // Simulate mouse movement and click
  const mouseMoveEvent = new MouseEvent('mousemove', {
    view: window,
    bubbles: true,
    cancelable: true,
    clientX: rect.x + rect.width / 2,
    clientY: rect.y + rect.height / 2
  });

  const mousedownEvent = new MouseEvent('mousedown', {
    view: window,
    bubbles: true,
    cancelable: true,
    button: 0,
    clientX: rect.x + rect.width / 2,
    clientY: rect.y + rect.height / 2
  });

  const mouseupEvent = new MouseEvent('mouseup', {
    view: window,
    bubbles: true,
    cancelable: true,
    button: 0,
    clientX: rect.x + rect.width / 2,
    clientY: rect.y + rect.height / 2
  });

  const clickEvent = new MouseEvent('click', {
    view: window,
    bubbles: true,
    cancelable: true,
    button: 0,
    clientX: rect.x + rect.width / 2,
    clientY: rect.y + rect.height / 2
  });

  // Dispatch all events
  document.dispatchEvent(mouseMoveEvent);
  labelOrParent.dispatchEvent(mousedownEvent);
  await new Promise(r => setTimeout(r, 100));
  labelOrParent.dispatchEvent(mouseupEvent);
  labelOrParent.dispatchEvent(clickEvent);
  checkbox.click();

  return {
    dispatched: true,
    rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
    checkboxChecked: checkbox.checked
  };
}
